<?php
session_start();
require_once '../config/database.php';

if (!isset($_SESSION['user'])) {
    header("Location: login.php");
    exit;
}

if (empty($_GET['traversee_id'])) {
    die("❌ Voyage non spécifié.");
}

$traversee_id = (int) $_GET['traversee_id'];

/* =========================================
   📋 INFOS VOYAGE
========================================= */
$stmt = $pdo->prepare("SELECT * FROM traversees WHERE id = ?");
$stmt->execute([$traversee_id]);
$traversee = $stmt->fetch();

if (!$traversee) {
    die("❌ Voyage introuvable.");
}

/* =========================================
   📋 BILLETS EMBARQUES
========================================= */
$sql = "
SELECT
    b.*,
    p.type_place,
    p.numero_place
FROM billets b
LEFT JOIN places p
    ON b.id_place = p.id_place
WHERE b.traversee_id = ?
AND b.statut = 'embarque'
ORDER BY p.type_place, p.numero_place
";

$stmt = $pdo->prepare($sql);
$stmt->execute([$traversee_id]);
$billets = $stmt->fetchAll();

/* =========================================
   🗺️ MAPPING (identique à acheter.php)
========================================= */
function mapPlace($type){

    $type = strtolower(trim($type));

    if(strpos($type,'cabine 2 places homme') !== false)
        return "Cabine 2 places Homme";

    if(strpos($type,'cabine 2 places femme') !== false)
        return "Cabine 2 places Femme";

    if(strpos($type,'cabine 4 places homme') !== false)
        return "Cabine 4 places Homme";

    if(strpos($type,'cabine 4 places femme') !== false)
        return "Cabine 4 places Femme";

    if(strpos($type,'cabine 4 places mixte') !== false)
        return "Cabine 4 places Mixte";

    if(strpos($type,'cabine 8 places homme') !== false)
        return "Cabine 8 places Homme";

    if(strpos($type,'cabine 8 places femme') !== false)
        return "Cabine 8 places Femme";

    if(strpos($type,'cabine 8 places mixte') !== false)
        return "Cabine 8 places Mixte";

    if(strpos($type,'pullman') !== false)
        return "Pullman";

    return $type;
}

/* =========================================
   💰 RECAPITULATIF
========================================= */
$homme = 0;
$femme = 0;
$non_renseigne = 0;

// Compteur par catégorie exacte (mêmes libellés que $tarifs dans acheter.php)
$stats_places = [
    "Cabine 2 places Homme" => 0,
    "Cabine 2 places Femme" => 0,

    "Cabine 4 places Homme" => 0,
    "Cabine 4 places Femme" => 0,
    "Cabine 4 places Mixte" => 0,

    "Cabine 8 places Homme" => 0,
    "Cabine 8 places Femme" => 0,
    "Cabine 8 places Mixte" => 0,

    "Pullman" => 0,
];

// Filet de sécurité pour les types_place non reconnus par mapPlace() (ex: "Chaise")
$autres_places = [];

foreach ($billets as $b) {

    $sexe = strtoupper(trim($b['sexe'] ?? ''));

    if ($sexe === 'M') {
        $homme++;
    } elseif ($sexe === 'F') {
        $femme++;
    } else {
        $non_renseigne++;
    }

    $categorie = mapPlace($b['type_place'] ?? '');

    if (isset($stats_places[$categorie])) {
        $stats_places[$categorie]++;
    } else {
        if (!isset($autres_places[$categorie])) {
            $autres_places[$categorie] = 0;
        }
        $autres_places[$categorie]++;
    }
}

/* =========================================
   📊 TOTAUX PAR TAILLE DE CABINE
========================================= */
$total_cabine_2 = $stats_places["Cabine 2 places Homme"]
                 + $stats_places["Cabine 2 places Femme"];

$total_cabine_4 = $stats_places["Cabine 4 places Homme"]
                 + $stats_places["Cabine 4 places Femme"]
                 + $stats_places["Cabine 4 places Mixte"];

$total_cabine_8 = $stats_places["Cabine 8 places Homme"]
                 + $stats_places["Cabine 8 places Femme"]
                 + $stats_places["Cabine 8 places Mixte"];

$total_pullman = $stats_places["Pullman"];

$total_passagers = count($billets);

// Date/heure d'édition (comme "Edité le ..." du PDF)
$edite_le = date('d-m-Y H:i:s');

// Logo COSAMA encodé en base64 (autonome, pas besoin de fichier externe)
$logo_cosama_base64 = '';
